-- Sholazar Basin: combat SmartAI for 36 creatures that cast no spell here and had no AI.
-- Rows from 5.4.8 (Legends of Azeroth), taken only where every event, action and target type is numbered the same in this core,
-- every spell is in the client data and 3.3.5 casts at least half of the same spells. Quest, summon and waypoint scripts are not included.
UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE `entry` IN (28001,28002,28003,28004,28011,28024,28025,28069,28076,28078,28079,28080,28081,28101,28108,28112,28123,28124,28129,28188,28297,28373,28378,28380,28408,28443,28467,28538,29013,29036,29044,29123,29124,30737,32485,32517) AND `ScriptName` = '';
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND `entryorguid` IN (28001,28002,28003,28004,28011,28024,28025,28069,28076,28078,28079,28080,28081,28101,28108,28112,28123,28124,28129,28188,28297,28373,28378,28380,28408,28443,28467,28538,29013,29036,29044,29123,29124,30737,32485,32517);
DELETE FROM `creature_text` WHERE `entry` IN (28076,28078);
